/* ── SVG curve divider (used when no bg image OR user disables adoption) ── */
.wb-addon-ultra_nav_header .nav-shape-divider {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  height: clamp(0px, var(--curve-height, 36px), 120px);
  overflow: hidden;
  line-height: 0;
  pointer-events: none;
  z-index: 5;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.18));
  transition: height 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.3s ease;
}

