.wb-lg-card-topics{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:10px}
.wb-lg-topic{display:inline-block;padding:3px 9px;border-radius:999px;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font-size:.68rem;font-weight:700;letter-spacing:.02em}
.wb-lg-card-summary{font-size:.86rem;color:var(--text-muted,#94a3b8);line-height:1.55;margin:0}
.wb-lg-card-footer{padding:0 18px 16px}
.wb-lg-view-btn{width:100%;padding:10px 14px;border-radius:9px;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font:inherit;font-weight:700;font-size:.84rem;cursor:pointer;transition:all .2s ease}
.wb-lg-view-btn:hover,.wb-lg-view-btn:focus-visible{background:var(--lg-accent);color:#fff;border-color:var(--lg-accent);transform:translateY(-1px)}
.wb-lg-search-bar{margin-bottom:18px}
.wb-lg-search-input{width:100%;padding:11px 16px;border-radius:10px;border:1px solid var(--border-subtle,rgba(255,255,255,.1));background:var(--bg-card,#131b2e);color:var(--text-main,#f8fafc);font:inherit;font-size:.92rem}
.wb-lg-search-input:focus{outline:none;border-color:var(--lg-accent);box-shadow:0 0 0 3px var(--lg-accent-soft)}
.wb-lg-list{display:flex;flex-direction:column;gap:10px}
.wb-lg-list-row{display:flex;align-items:center;gap:14px;padding:12px 16px;border-radius:12px;background:var(--bg-card,rgba(23,34,59,.6));border:1px solid var(--border-subtle,rgba(255,255,255,.08));cursor:pointer;transition:all .2s ease}
.wb-lg-list-row:hover,.wb-lg-list-row:focus-visible{border-color:var(--lg-accent);transform:translateX(3px);outline:none}
.wb-lg-list-row[hidden]{display:none}
.wb-lg-list-photo{width:54px;height:54px;border-radius:12px;overflow:hidden;flex-shrink:0;background:var(--lg-accent)}
.wb-lg-list-photo img{width:100%;height:100%;object-fit:cover;display:block}
.wb-lg-list-info{flex:1;min-width:0}
.wb-lg-list-name{font-weight:700;font-size:.96rem;color:var(--text-main,#f8fafc);margin-bottom:4px}
.wb-lg-list-topics{display:flex;flex-wrap:wrap;gap:5px}
.wb-lg-topic-sm{font-size:.66rem;padding:2px 8px}
.wb-lg-view-sm{width:auto;padding:7px 14px;font-size:.78rem}
.wb-lg-list-empty{padding:32px 16px;text-align:center;color:var(--text-dim,#94a3b8);font-size:.9rem;display:none}
.wb-lg-list-empty[data-show="true"]{display:block}
.wb-lg-slider-wrap{position:relative;display:flex;align-items:center;gap:12px}
.wb-lg-slider-viewport{flex:1;overflow:hidden;border-radius:var(--radius-lg,16px);touch-action:pan-y}
.wb-lg-slider-track{display:flex;gap:16px;transition:transform .45s cubic-bezier(.25,.8,.25,1);will-change:transform}
.wb-lg-slide{flex-shrink:0;min-width:0}
.wb-lg-slider-btn{flex-shrink:0;width:42px;height:42px;border-radius:50%;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font:inherit;font-size:1.3rem;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .2s ease}
.wb-lg-slider-btn:hover,.wb-lg-slider-btn:focus-visible{background:var(--lg-accent);color:#fff;border-color:var(--lg-accent)}
.wb-lg-slider-btn:disabled{opacity:.35;cursor:not-allowed}
.wb-lg-slider-dots{display:flex;justify-content:center;gap:7px;margin-top:16px}
.wb-lg-dot{width:8px;height:8px;border-radius:50%;background:rgba(148,163,184,.35);border:0;padding:0;cursor:pointer;transition:all .2s ease}
.wb-lg-dot.active{width:22px;border-radius:4px;background:var(--lg-accent)}
.wb-lg-dot:focus-visible{outline:2px solid var(--lg-accent);outline-offset:3px}
.wb-lg-empty{text-align:center;padding:56px 20px;color:var(--text-dim,#94a3b8)}
.wb-lg-modal-overlay{position:fixed;inset:0;z-index:999999;background:rgba(0,0,0,.82);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:16px;animation:wb-lg-fade .2s ease}
@keyframes wb-lg-fade{from{opacity:0}to{opacity:1}}
.wb-lg-modal{width:100%;max-width:1080px;max-height:92vh;height:720px;background:linear-gradient(165deg,#0f172a 0%,#090d16 100%);border:1px solid var(--lg-accent-line);border-radius:20px;box-shadow:0 30px 80px rgba(0,0,0,.8);display:flex;flex-direction:column;overflow:hidden;position:relative;animation:wb-lg-pop .25s cubic-bezier(.16,1,.3,1)}
@keyframes wb-lg-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:scale(1)}}
.wb-lg-modal-closing{animation:wb-lg-fade .2s ease reverse}
.wb-lg-modal-close{position:absolute;top:16px;right:16px;z-index:3;width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);color:#fff;font:inherit;font-size:1.1rem;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .15s ease}
.wb-lg-modal-close:hover,.wb-lg-modal-close:focus-visible{background:#ef4444;border-color:#ef4444}
.wb-lg-modal-header{padding:20px 24px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
.wb-lg-modal-header-title{display:flex;align-items:center;gap:12px}
.wb-lg-modal-header-title h3{margin:0;font-size:1.15rem;font-weight:800;color:#fff}
.wb-lg-modal-header-subtitle{margin:2px 0 0;font-size:.78rem;color:#94a3b8}
.wb-lg-modal-badge{padding:5px 12px;border-radius:999px;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font-size:.72rem;font-weight:700}
.wb-lg-modal-split{display:flex;flex:1;min-height:0}
.wb-lg-modal--list-right .wb-lg-modal-split{flex-direction:row-reverse}
.wb-lg-modal-sidebar{width:320px;flex-shrink:0;border-right:1px solid rgba(255,255,255,.08);display:flex;flex-direction:column;background:rgba(15,23,42,.6)}
.wb-lg-modal--list-right .wb-lg-modal-sidebar{border-right:none;border-left:1px solid rgba(255,255,255,.08)}
.wb-lg-sidebar-search-box{padding:14px;border-bottom:1px solid rgba(255,255,255,.06);position:relative}
.wb-lg-sidebar-search-icon{position:absolute;left:26px;top:50%;transform:translateY(-50%);font-size:.88rem;opacity:.6;pointer-events:none}
.wb-lg-sidebar-search-input{width:100%;padding:9px 12px 9px 36px;border-radius:8px;background:rgba(15,23,42,.9);border:1px solid rgba(255,255,255,.1);color:#f1f5f9;font:inherit;font-size:.85rem}
.wb-lg-sidebar-search-input:focus{outline:none;border-color:var(--lg-accent)}
.wb-lg-sidebar-list{flex:1;overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:4px}
.wb-lg-sidebar-item{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:10px;cursor:pointer;transition:all .15s ease;border:1px solid transparent;background:none;text-align:left;font:inherit;color:inherit}
.wb-lg-sidebar-item:hover{background:var(--lg-accent-soft)}
.wb-lg-sidebar-item.is-active{background:var(--lg-accent-soft);border-color:var(--lg-accent-line)}
.wb-lg-sidebar-item:focus-visible{outline:2px solid var(--lg-accent);outline-offset:0}
.wb-lg-sidebar-item[hidden]{display:none}
.wb-lg-sidebar-avatar{width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:var(--lg-accent)}
.wb-lg-sidebar-avatar img{width:100%;height:100%;object-fit:cover;display:block}
.wb-lg-sidebar-info{flex:1;min-width:0}
.wb-lg-sidebar-name{font-size:.85rem;font-weight:700;color:#f8fafc;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wb-lg-sidebar-topics{display:flex;flex-wrap:wrap;gap:3px}
.wb-lg-sidebar-pill{font-size:.6rem;padding:1px 6px;border-radius:999px;background:var(--lg-accent-soft);color:var(--lg-accent-text);font-weight:600}
.wb-lg-sidebar-arrow{color:#64748b;font-size:1.1rem}
.wb-lg-sidebar-empty{padding:30px 20px;text-align:center;color:#64748b;font-size:.82rem}
.wb-lg-modal-detail{flex:1;display:flex;flex-direction:column;min-width:0;overflow:hidden}
.wb-lg-detail-scroll{flex:1;overflow-y:auto;padding:24px}
.wb-lg-detail-top{display:flex;gap:22px;margin-bottom:24px;align-items:flex-start;flex-wrap:wrap}
.wb-lg-detail-photo{width:140px;height:140px;border-radius:16px;overflow:hidden;box-shadow:0 12px 30px -8px color-mix(in srgb,var(--lg-accent) 50%,transparent);background:var(--lg-accent);flex-shrink:0}
.wb-lg-detail-photo img{width:100%;height:100%;object-fit:cover;display:block}
.wb-lg-detail-info{flex:1;min-width:200px}
.wb-lg-detail-badge{display:inline-block;padding:3px 10px;border-radius:999px;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font-size:.7rem;font-weight:700;margin-bottom:8px}
.wb-lg-detail-name{font-size:1.6rem;font-weight:800;color:#fff;margin:0 0 10px;line-height:1.2}
.wb-lg-detail-topics{display:flex;flex-wrap:wrap;gap:6px}
.wb-lg-topic-md{font-size:.75rem;padding:4px 11px}
.wb-lg-detail-body{padding-top:20px;border-top:1px solid rgba(255,255,255,.08)}
.wb-lg-detail-section-title{font-size:.9rem;font-weight:800;color:#f8fafc;margin-bottom:12px;display:flex;align-items:center;gap:7px}
.wb-lg-detail-summary{font-size:.92rem;line-height:1.7;color:#cbd5e1;white-space:pre-wrap}
.wb-lg-detail-footer{padding:14px 24px;border-top:1px solid rgba(255,255,255,.08);background:rgba(9,13,22,.7);display:flex;align-items:center;justify-content:space-between;gap:12px}
.wb-lg-detail-nav-btn{padding:9px 16px;border-radius:8px;background:var(--lg-accent-soft);border:1px solid var(--lg-accent-line);color:var(--lg-accent-text);font:inherit;font-size:.82rem;font-weight:700;cursor:pointer;transition:all .15s ease}
.wb-lg-detail-nav-btn:hover,.wb-lg-detail-nav-btn:focus-visible{background:var(--lg-accent);color:#fff}
.wb-lg-detail-page{font-size:.78rem;color:#94a3b8;font-weight:600}
@media(max-width:820px){.wb-lg-modal{height:90vh}.wb-lg-modal-split{flex-direction:column}.wb-lg-modal-sidebar{width:100%;max-height:40vh;border-right:none;border-bottom:1px solid rgba(255,255,255,.08)}.wb-lg-modal--list-right .wb-lg-modal-sidebar{border-left:none}.wb-lg-detail-photo{width:100px;height:100px}.wb-lg-detail-name{font-size:1.3rem}}
@media(prefers-reduced-motion:reduce){.wb-addon-lecturer-gallery *{transition:none!important;animation:none!important;scroll-behavior:auto!important}}

customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-lecturer-gallery');
  if (!root) return;

  var uid = 'wb-lg-' + Math.random().toString(36).slice(2, 8);
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || root).querySelectorAll(sel)); };
  var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  var state = {
    lecturers: Array.isArray(props.lecturers) ? props.lecturers.filter(function (l) { return l && l.name; }) : [],
    activeIdx: 0,
    query: '',
    sheetLoaded: false,
    destroyed: false
  };

  var mode = props.viewMode || 'gallery';
  var cols = parseInt(props.columns) || 3;
  var spv = Math.max(1, parseInt(props.slidesPerView) || 3);
  var autoPlay = (props.autoPlay === true || props.autoPlay === 'true') && !prefersReduced;
  var autoSpeed = Math.max(2, parseInt(props.autoPlaySpeed) || 4) * 1000;
  var showSearch = props.showSearch !== false && props.showSearch !== 'false';
  var cardStyle = props.cardStyle || 'modern';
  var modalPos = props.modalListPosition || 'left';
  var showTopics = props.showTopics !== false && props.showTopics !== 'false';
  var showSummary = props.showSummary !== false && props.showSummary !== 'false';
  var accent = props.accentColor || '#6366f1';

  root.style.setProperty('--lg-accent', accent);

  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (!e.isIntersecting) return;
      var img = e.target;
      if (img.dataset.src) { img.src = img.dataset.src; img.removeAttribute('data-src'); }
      io.unobserve(img);
    });
  }, { rootMargin: '150px' }) : null;

  function lazyImg(src, alt, cls) {
    var safe = esc(src); var a = esc(alt);
    if (io) return '<img class="' + cls + '" data-src="' + safe + '" alt="' + a + '" onerror="this.style.display=&#39;none&#39;;this.parentNode.querySelector(&#39;.wb-lg-avatar&#39;).style.display=&#39;flex&#39;">';
    return '<img class="' + cls + '" src="' + safe + '" alt="' + a + '" loading="lazy" onerror="this.style.display=&#39;none&#39;;this.parentNode.querySelector(&#39;.wb-lg-avatar&#39;).style.display=&#39;flex&#39;">';
  }
  function avatar(name, size) {
    var initial = (name || '?').trim().charAt(0).toUpperCase() || '?';
    return '<div class="wb-lg-avatar" style="font-size:' + size + 'px;display:flex">' + esc(initial) + '</div>';
  }

  function cardHtml(l, i) {
    var hasPhoto = !!(l.photoUrl && l.photoUrl.trim());
    var photo = hasPhoto
      ? lazyImg(l.photoUrl, l.name || '', 'wb-lg-card-img') + avatar(l.name, 48)
      : avatar(l.name, 48);
    var topics = '';
    if (showTopics && l.topics) {
      topics = '<div class="wb-lg-card-topics">' + String(l.topics).split(',').filter(function (t) { return t.trim(); }).map(function (t) { return '<span class="wb-lg-topic">' + esc(t.trim()) + '</span>'; }).join('') + '</div>';
    }
    var summary = '';
    if (showSummary) {
      var full = l.summary || 'No summary provided.';
      var short = full.length > 130 ? full.slice(0, 130) + '…' : full;
      summary = '<p class="wb-lg-card-summary">' + esc(short) + '</p>';
    }
    return '<article class="wb-lg-card wb-lg-card--' + esc(cardStyle) + '" data-lg-idx="' + i + '" role="button" tabindex="0" aria-label="View profile of ' + esc(l.name || 'Unnamed') + '"><div class="wb-lg-card-photo">' + photo + '</div><div class="wb-lg-card-body"><h3 class="wb-lg-card-name">' + esc(l.name || 'Unnamed') + '</h3>' + topics + summary + '</div><div class="wb-lg-card-footer"><button type="button" class="wb-lg-view-btn" data-lg-idx="' + i + '">View Profile →</button></div></article>';
  }

  var slider = null;
  function renderBody() {
    var body = $('[data-lg-mount="body"]');
    if (!body) return;
    if (!state.lecturers.length) {
      body.innerHTML = '<div class="wb-lg-empty"><div style="font-size:2.4rem;margin-bottom:10px;">🎓</div><div style="font-weight:700;font-size:1rem;color:#e2e8f0;">No Lecturers Added Yet</div><div style="font-size:.84rem;color:#64748b;margin-top:6px;">Add profiles in the Inspector, or set a Google Sheet URL.</div></div>';
      return;
    }
    if (mode === 'gallery') {
      body.innerHTML = '<div class="wb-lg-grid" data-cols="' + cols + '">' + state.lecturers.map(cardHtml).join('') + '</div>';
    } else if (mode === 'list') {
      var searchBar = showSearch ? '<div class="wb-lg-search-bar"><input type="text" class="wb-lg-search-input" placeholder="🔍 Search by name or topic…" aria-label="Search lecturers"></div>' : '';
      var rows = state.lecturers.map(function (l, i) {
        var hasPhoto = !!(l.photoUrl && l.photoUrl.trim());
        var photo = hasPhoto ? lazyImg(l.photoUrl, l.name || '', 'wb-lg-list-img') + avatar(l.name, 20) : avatar(l.name, 20);
        var topics = String(l.topics || '').split(',').filter(function (t) { return t.trim(); }).map(function (t) { return '<span class="wb-lg-topic wb-lg-topic-sm">' + esc(t.trim()) + '</span>'; }).join('');
        var hay = (l.name || '') + ' ' + (l.topics || '');
        return '<article class="wb-lg-list-row" data-lg-idx="' + i + '" data-search="' + esc(hay.toLowerCase()) + '" role="button" tabindex="0" aria-label="View profile of ' + esc(l.name || 'Unnamed') + '"><div class="wb-lg-list-photo">' + photo + '</div><div class="wb-lg-list-info"><div class="wb-lg-list-name">' + esc(l.name || 'Unnamed') + '</div><div class="wb-lg-list-topics">' + topics + '</div></div><button type="button" class="wb-lg-view-btn wb-lg-view-sm" data-lg-idx="' + i + '">View →</button></article>';
      }).join('');
      body.innerHTML = searchBar + '<div class="wb-lg-list">' + rows + '</div><div class="wb-lg-list-empty" aria-live="polite">No lecturers match your search.</div>';
    } else if (mode === 'slider') {
      var slideW = 100 / spv;
      var total = Math.max(1, Math.ceil(state.lecturers.length / spv));
      var slides = state.lecturers.map(function (l, i) {
        return '<div class="wb-lg-slide" style="min-width:calc(' + slideW + '% - ' + (16 * (spv - 1) / spv) + 'px);max-width:calc(' + slideW + '% - ' + (16 * (spv - 1) / spv) + 'px);">' + cardHtml(l, i) + '</div>';
      }).join('');
      var dots = '';
      for (var d = 0; d < total; d++) dots += '<button type="button" class="wb-lg-dot' + (d === 0 ? ' active' : '') + '" data-slide="' + d + '" aria-label="Go to slide ' + (d + 1) + '"></button>';
      body.innerHTML = '<div class="wb-lg-slider-wrap"><button type="button" class="wb-lg-slider-btn wb-lg-prev" aria-label="Previous slide">‹</button><div class="wb-lg-slider-viewport"><div class="wb-lg-slider-track">' + slides + '</div></div><button type="button" class="wb-lg-slider-btn wb-lg-next" aria-label="Next slide">›</button></div><div class="wb-lg-slider-dots" role="tablist" aria-label="Slide navigation">' + dots + '</div>';
    }
    bindBody();
  }

  function initSlider() {
    var track = $('.wb-lg-slider-track');
    if (!track) return;
    var prevBtn = $('.wb-lg-prev'), nextBtn = $('.wb-lg-next');
    var dots = $$('.wb-lg-dot');
    var total = Math.max(1, Math.ceil(state.lecturers.length / spv));
    var current = 0, timer = null, touchStartX = 0, touchDeltaX = 0;
    var viewport = $('.wb-lg-slider-viewport');

    function goTo(idx) {
      if (idx < 0) idx = 0;
      if (idx >= total) idx = total - 1;
      current = idx;
      var pct = -(idx * 100) / total;
      track.style.transform = 'translateX(' + pct + '%)';
      dots.forEach(function (d, i) { d.classList.toggle('active', i === idx); d.setAttribute('aria-selected', i === idx ? 'true' : 'false'); });
      if (prevBtn) prevBtn.disabled = idx === 0;
      if (nextBtn) nextBtn.disabled = idx === total - 1;
    }
    function start() { if (autoPlay && total > 1 && !timer) timer = setInterval(function () { goTo(current + 1 >= total ? 0 : current + 1); }, autoSpeed); }
    function stop() { if (timer) { clearInterval(timer); timer = null; } }
    function reset() { stop(); start(); }

    if (prevBtn) prevBtn.addEventListener('click', function (e) { e.stopPropagation(); goTo(current - 1); reset(); });
    if (nextBtn) nextBtn.addEventListener('click', function (e) { e.stopPropagation(); goTo(current + 1); reset(); });
    dots.forEach(function (dot) { dot.addEventListener('click', function () { goTo(parseInt(dot.dataset.slide, 10) || 0); reset(); }); });

    root.addEventListener('mouseenter', stop);
    root.addEventListener('mouseleave', start);
    root.addEventListener('focusin', stop);
    root.addEventListener('focusout', start);

    if (viewport) {
      viewport.addEventListener('touchstart', function (e) { touchStartX = e.touches[0].clientX; touchDeltaX = 0; stop(); }, { passive: true });
      viewport.addEventListener('touchmove', function (e) { touchDeltaX = e.touches[0].clientX - touchStartX; }, { passive: true });
      viewport.addEventListener('touchend', function () {
        if (Math.abs(touchDeltaX) > 40) goTo(touchDeltaX < 0 ? current + 1 : current - 1);
        touchDeltaX = 0; start();
      });
    }
    goTo(0);
    start();
    return { destroy: stop, goTo: goTo };
  }

  var bodyDelegated = false;
  function bindBody() {
    if (mode === 'slider') slider = initSlider();
    if (bodyDelegated) return;
    bodyDelegated = true;
    var body = $('[data-lg-mount="body"]');
    if (!body) return;

    body.addEventListener('click', function (e) {
      var btn = e.target.closest('.wb-lg-view-btn');
      if (btn) { e.stopPropagation(); openModal(parseInt(btn.dataset.lgIdx, 10) || 0); return; }
      var card = e.target.closest('.wb-lg-card, .wb-lg-list-row');
      if (card && !e.target.closest('button')) { openModal(parseInt(card.dataset.lgIdx, 10) || 0); }
    });
    body.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      var card = e.target.closest('.wb-lg-card, .wb-lg-list-row');
      if (card && e.target === card) { e.preventDefault(); openModal(parseInt(card.dataset.lgIdx, 10) || 0); }
    });

    var searchInput = body.querySelector('.wb-lg-search-input');
    if (searchInput) {
      var tId = null;
      searchInput.addEventListener('input', function () {
        clearTimeout(tId);
        tId = setTimeout(function () {
          var q = searchInput.value.toLowerCase().trim();
          state.query = q;
          var rows = $$('.wb-lg-list-row', body);
          var visible = 0;
          rows.forEach(function (r) {
            var match = !q || (r.dataset.search || '').indexOf(q) !== -1;
            r.hidden = !match;
            if (match) visible++;
          });
          var emptyEl = body.querySelector('.wb-lg-list-empty');
          if (emptyEl) emptyEl.dataset.show = (!visible && q) ? 'true' : 'false';
        }, 120);
      });
    }
  }

  function openModal(startIdx) {
    var prev = document.getElementById(uid + '-modal');
    if (prev) prev.remove();
    var opener = document.activeElement;
    var activeIdx = Math.max(0, Math.min(startIdx, state.lecturers.length - 1));

    var overlay = document.createElement('div');
    overlay.id = uid + '-modal';
    overlay.className = 'wb-lg-modal-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Lecturer and speaker directory');

    var listClass = modalPos === 'right' ? ' wb-lg-modal--list-right' : '';
    overlay.innerHTML =
      '<div class="wb-lg-modal' + listClass + '">' +
        '<button type="button" class="wb-lg-modal-close" aria-label="Close dialog">✕</button>' +
        '<div class="wb-lg-modal-header"><div class="wb-lg-modal-header-title"><span style="font-size:1.7rem">🎓</span><div><h3>Lecturer & Speaker Directory</h3><p class="wb-lg-modal-header-subtitle">Browse profiles, topics, and bios</p></div></div><div class="wb-lg-modal-badge">' + state.lecturers.length + ' Speakers</div></div>' +
        '<div class="wb-lg-modal-split">' +
          '<aside class="wb-lg-modal-sidebar"><div class="wb-lg-sidebar-search-box"><span class="wb-lg-sidebar-search-icon">🔍</span><input type="text" class="wb-lg-sidebar-search-input" placeholder="Search name or topic…" aria-label="Search speakers"></div><div class="wb-lg-sidebar-list" role="list"></div></aside>' +
          '<div class="wb-lg-modal-detail"></div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(overlay);

    var sbw = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.paddingRight = (parseFloat(getComputedStyle(document.body).paddingRight) || 0) + sbw + 'px';
    document.body.style.overflow = 'hidden';

    var sidebarList = overlay.querySelector('.wb-lg-sidebar-list');
    var searchInput = overlay.querySelector('.wb-lg-sidebar-search-input');
    var detailPane = overlay.querySelector('.wb-lg-modal-detail');
    var closeBtn = overlay.querySelector('.wb-lg-modal-close');

    function closeModal() {
      overlay.classList.add('wb-lg-modal-closing');
      document.removeEventListener('keydown', keyHandler, true);
      setTimeout(function () {
        overlay.remove();
        document.body.style.overflow = '';
        document.body.style.paddingRight = '';
        if (opener && opener.focus) { try { opener.focus(); } catch (e) {} }
      }, 180);
    }

    function renderSidebar(q) {
      q = (q || '').toLowerCase().trim();
      var html = state.lecturers.map(function (l, i) {
        var name = l.name || 'Unnamed';
        var topics = l.topics || '';
        var match = !q || name.toLowerCase().indexOf(q) !== -1 || topics.toLowerCase().indexOf(q) !== -1;
        var hasPhoto = !!(l.photoUrl && l.photoUrl.trim());
        var photo = hasPhoto ? lazyImg(l.photoUrl, name, 'wb-lg-list-img') + avatar(name, 16) : avatar(name, 16);
        var pills = topics.split(',').filter(function (t) { return t.trim(); }).slice(0, 2).map(function (t) { return '<span class="wb-lg-sidebar-pill">' + esc(t.trim()) + '</span>'; }).join('');
        return '<button type="button" class="wb-lg-sidebar-item' + (i === activeIdx ? ' is-active' : '') + '" data-idx="' + i + '" ' + (match ? '' : 'hidden ') + 'role="listitem" aria-selected="' + (i === activeIdx) + '"><div class="wb-lg-sidebar-avatar">' + photo + '</div><div class="wb-lg-sidebar-info"><div class="wb-lg-sidebar-name">' + esc(name) + '</div><div class="wb-lg-sidebar-topics">' + (pills || '<span class="wb-lg-sidebar-pill">Speaker</span>') + '</div></div><span class="wb-lg-sidebar-arrow" aria-hidden="true">›</span></button>';
      }).join('');
      sidebarList.innerHTML = html || '<div class="wb-lg-sidebar-empty">No matches.</div>';
    }

    function renderDetail() {
      var l = state.lecturers[activeIdx] || {};
      var name = l.name || 'Unnamed';
      var topics = l.topics || '';
      var summary = l.summary || 'No summary or biography provided for this lecturer.';
      var hasPhoto = !!(l.photoUrl && l.photoUrl.trim());
      var photo = '<div class="wb-lg-detail-photo">' + (hasPhoto ? lazyImg(l.photoUrl, name, 'wb-lg-detail-img') : '') + avatar(name, 44) + '</div>';
      var tags = topics.split(',').filter(function (t) { return t.trim(); }).map(function (t) { return '<span class="wb-lg-topic wb-lg-topic-md">' + esc(t.trim()) + '</span>'; }).join('') || '<span class="wb-lg-topic wb-lg-topic-md">General</span>';
      detailPane.innerHTML =
        '<div class="wb-lg-detail-scroll">' +
          '<div class="wb-lg-detail-top">' + photo +
            '<div class="wb-lg-detail-info"><div class="wb-lg-detail-badge">Featured Speaker</div><h2 class="wb-lg-detail-name">' + esc(name) + '</h2><div class="wb-lg-detail-topics">' + tags + '</div></div>' +
          '</div>' +
          '<div class="wb-lg-detail-body"><div class="wb-lg-detail-section-title"><span>📖</span> Profile & Background Summary</div><div class="wb-lg-detail-summary">' + esc(summary) + '</div></div>' +
        '</div>' +
        '<div class="wb-lg-detail-footer"><button type="button" class="wb-lg-detail-nav-btn wb-lg-detail-prev">← Previous</button><div class="wb-lg-detail-page">' + (activeIdx + 1) + ' of ' + state.lecturers.length + '</div><button type="button" class="wb-lg-detail-nav-btn wb-lg-detail-next">Next →</button></div>';
      var prevBtn = detailPane.querySelector('.wb-lg-detail-prev');
      var nextBtn = detailPane.querySelector('.wb-lg-detail-next');
      if (prevBtn) prevBtn.addEventListener('click', function () { switchTo((activeIdx - 1 + state.lecturers.length) % state.lecturers.length); });
      if (nextBtn) nextBtn.addEventListener('click', function () { switchTo((activeIdx + 1) % state.lecturers.length); });
      detailPane.querySelector('.wb-lg-detail-scroll').scrollTop = 0;
    }

    function switchTo(idx) {
      activeIdx = idx;
      $$('.wb-lg-sidebar-item', sidebarList).forEach(function (item) {
        var i = parseInt(item.dataset.idx, 10);
        item.classList.toggle('is-active', i === activeIdx);
        item.setAttribute('aria-selected', i === activeIdx ? 'true' : 'false');
        if (i === activeIdx) item.scrollIntoView({ block: 'nearest', behavior: prefersReduced ? 'auto' : 'smooth' });
      });
      renderDetail();
    }

    function keyHandler(e) {
      if (e.key === 'Escape') { e.preventDefault(); closeModal(); return; }
      if (e.key === 'Tab') {
        var focusables = overlay.querySelectorAll('button, input, [tabindex]:not([tabindex="-1"])');
        var first = focusables[0], last = focusables[focusables.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        return;
      }
      if (document.activeElement === searchInput) return;
      if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); switchTo((activeIdx - 1 + state.lecturers.length) % state.lecturers.length); }
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); switchTo((activeIdx + 1) % state.lecturers.length); }
    }

    closeBtn.addEventListener('click', closeModal);
    overlay.addEventListener('click', function (e) { if (e.target === overlay) closeModal(); });
    document.addEventListener('keydown', keyHandler, true);
    sidebarList.addEventListener('click', function (e) { var b = e.target.closest('.wb-lg-sidebar-item'); if (b) switchTo(parseInt(b.dataset.idx, 10)); });
    var sId = null;
    searchInput.addEventListener('input', function () { clearTimeout(sId); sId = setTimeout(function () { renderSidebar(searchInput.value); }, 120); });

    renderSidebar('');
    renderDetail();
    if (io) $$('.wb-lg-modal img[data-src]').forEach(function (img) { io.observe(img); });
    setTimeout(function () { closeBtn.focus(); }, 50);
  }

  function normalizeSheetUrl(url) {
    if (!url) return '';
    var clean = String(url).trim();
    if (!clean) return '';
    if (clean.indexOf('/pub?output=csv') !== -1 || clean.indexOf('/export?format=csv') !== -1) return clean;
    if (clean.indexOf('/pubhtml') !== -1) return clean.replace('/pubhtml', '/pub?output=csv');
    if (clean.indexOf('/pub?') !== -1 && clean.indexOf('output=csv') === -1) return clean + '&output=csv';
    if (clean.indexOf('gviz/tq') !== -1) return clean;
    var m = clean.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (m && m[1]) {
      var gidM = clean.match(/[#&?]gid=([0-9]+)/);
      var gid = gidM ? gidM[1] : '0';
      return 'https://docs.google.com/spreadsheets/d/' + m[1] + '/export?format=csv&gid=' + gid;
    }
    return clean;
  }

  function parseCsv(text) {
    var rows = [[]], row = rows[0], inQ = false, cur = '';
    for (var i = 0; i < text.length; i++) {
      var c = text[i], n = text[i + 1];
      if (c === '"') { if (inQ && n === '"') { cur += '"'; i++; } else { inQ = !inQ; } }
      else if (c === ',' && !inQ) { row.push(cur); cur = ''; }
      else if ((c === '\r' || c === '\n') && !inQ) {
        if (c === '\r' && n === '\n') i++;
        row.push(cur); cur = ''; row = []; rows.push(row);
      } else { cur += c; }
    }
    if (cur.length || row.length > 1) { row.push(cur); }
    return rows.filter(function (r) { return r.some(function (c) { return c && c.trim(); }); });
  }

  function setBadge(icon, text) { var b = root.querySelector('.wb-lg-sync-badge'); if (b) b.innerHTML = '<span>' + icon + '</span> ' + esc(text); }

  function syncFromSheet() {
    var raw = props.googleSheetUrl;
    if (!raw) return;
    var url = normalizeSheetUrl(raw);
    if (!url) return;
    setBadge('⏳', 'Fetching sheet…');
    var ctrl = ('AbortController' in window) ? new AbortController() : null;
    var to = setTimeout(function () { if (ctrl) ctrl.abort(); }, 15000);

    fetch(url, { signal: ctrl ? ctrl.signal : undefined, credentials: 'omit' })
      .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
      .then(function (text) {
        clearTimeout(to);
        if (!text || text.indexOf('<!DOCTYPE') === 0) throw new Error('Returned HTML — is the sheet public?');
        var rows = parseCsv(text);
        if (rows.length < 2) throw new Error('No data rows');
        var headers = rows[0].map(function (h) { return (h || '').toLowerCase().trim(); });
        var priorities = [
          { key: 'name', terms: ['name', 'lecturer', 'speaker', 'faculty', 'presenter', 'instructor'] },
          { key: 'photoUrl', terms: ['photo url', 'photo', 'image', 'picture', 'avatar', 'headshot', 'img'] },
          { key: 'topics', terms: ['topic', 'specialization', 'subject', 'expertise'] },
          { key: 'summary', terms: ['summary', 'biography', 'bio', 'profile', 'description', 'about'] }
        ];
        var idx = {};
        priorities.forEach(function (p) {
          for (var t = 0; t < p.terms.length; t++) {
            var found = headers.findIndex(function (h) { return h.indexOf(p.terms[t]) !== -1; });
            if (found !== -1) { idx[p.key] = found; break; }
          }
        });
        var items = [];
        for (var r = 1; r < rows.length; r++) {
          var row = rows[r];
          var name = idx.name != null ? (row[idx.name] || '').trim() : (row[0] || '').trim();
          if (!name) continue;
          items.push({
            name: name,
            photoUrl: idx.photoUrl != null ? (row[idx.photoUrl] || '').trim() : '',
            topics: idx.topics != null ? (row[idx.topics] || '').trim() : '',
            summary: idx.summary != null ? (row[idx.summary] || '').trim() : ''
          });
        }
        if (!items.length) throw new Error('No valid rows');
        state.lecturers = items;
        renderBody();
        setBadge('🟢', 'Synced (' + items.length + ' speakers)');
      })
      .catch(function (err) {
        clearTimeout(to);
        setBadge('⚠️', 'Sync error: ' + (err.name === 'AbortError' ? 'timeout' : err.message));
      });
  }

  renderBody();
  if (io) $$('img[data-src]', root).forEach(function (img) { io.observe(img); });
  if ((props.dataSource === 'google_sheets' || props.dataSource === 'Google Sheets (Live Sync via URL)') && props.googleSheetUrl) {
    syncFromSheet();
  }

  el.__wbDestroy = function () {
    state.destroyed = true;
    if (slider && slider.destroy) slider.destroy();
    if (io) io.disconnect();
    var m = document.getElementById(uid + '-modal');
    if (m) m.remove();
    document.body.style.overflow = '';
    document.body.style.paddingRight = '';
  };
}

