function onMount(el, props) {
  var root = el.querySelector('.wb-addon-contact-hire') || el;
  if (!root) return;

  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };

  var accent = props.accentColor || '#6366f1';
  root.style.setProperty('--ch-accent', accent);

  var svc = (props.emailServiceId || '').trim();
  var tpl = (props.emailTemplateId || '').trim();
  var pub = (props.emailPublicKey || '').trim();
  var configured = !!(svc && tpl && pub);

  // ── EmailJS loader ──────────────────────────────────────────────────────────
  function loadEmailJs(callback) {
    if (window.emailjs) {
      try { window.emailjs.init({ publicKey: pub }); } catch (e) {}
      if (callback) callback();
      return;
    }
    var existing = document.querySelector('script[src*="emailjs"]');
    if (existing) {
      existing.addEventListener('load', function () {
        try { window.emailjs.init({ publicKey: pub }); } catch (e) {}
        if (callback) callback();
      });
      return;
    }
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js';
    s.async = true;
    s.onload = function () {
      try { if (window.emailjs) window.emailjs.init({ publicKey: pub }); } catch (e) {}
      if (callback) callback();
    };
    document.head.appendChild(s);
  }

  if (configured) { loadEmailJs(); }

  // ── Form ────────────────────────────────────────────────────────────────────
  var formMount = $('[data-ch-mount="form"]');
  if (formMount) {
    var warn = configured ? '' : '<div class="wb-ch-config-warning">⚙️ <strong>Email sending is not configured yet.</strong><br>Go to the <strong>Advanced</strong> tab in the Inspector and enter your EmailJS Service ID, Template ID, and Public Key to activate this form.</div>';

    formMount.innerHTML =
      warn +
      '<div class="wb-ch-status" data-ch-status></div>' +
      '<form class="wb-ch-form" novalidate>' +
        '<div class="wb-ch-form-row">' +
          '<div class="wb-ch-field"><label class="wb-ch-label" for="ch-name">Your Name *</label><input class="wb-ch-input" id="ch-name" name="from_name" type="text" placeholder="Jane Doe" required></div>' +
          '<div class="wb-ch-field"><label class="wb-ch-label" for="ch-email">Your Email *</label><input class="wb-ch-input" id="ch-email" name="from_email" type="email" placeholder="jane@company.com" required></div>' +
        '</div>' +
        '<div class="wb-ch-field"><label class="wb-ch-label" for="ch-subject">Subject *</label><input class="wb-ch-input" id="ch-subject" name="subject" type="text" placeholder="Project Inquiry / Hire Request" required></div>' +
        '<div class="wb-ch-field"><label class="wb-ch-label" for="ch-message">Message *</label><textarea class="wb-ch-textarea" id="ch-message" name="message" placeholder="Tell me about your project, timeline, and budget…" required></textarea></div>' +
        '<button type="submit" class="wb-ch-submit" data-ch-submit><span aria-hidden="true">✉️</span> Send Message</button>' +
      '</form>';

    var form = formMount.querySelector('form');
    var statusEl = formMount.querySelector('[data-ch-status]');
    var submitBtn = formMount.querySelector('[data-ch-submit]');

    function setStatus(type, text) {
      statusEl.className = 'wb-ch-status wb-ch-status--' + type;
      statusEl.textContent = text;
    }

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (!configured) {
        setStatus('error', 'Email sending is not configured. Please contact the site owner directly.');
        return;
      }

      var data = {
        from_name: form.from_name.value.trim(),
        from_email: form.from_email.value.trim(),
        reply_to: form.from_email.value.trim(),
        subject: form.subject.value.trim(),
        message: form.message.value.trim(),
        to_name: props.recipientName || 'there'
      };

      if (!data.from_name || !data.from_email || !data.subject || !data.message) {
        setStatus('error', 'Please fill in all required fields before sending.');
        return;
      }

      submitBtn.disabled = true;
      setStatus('info', 'Sending your message…');

      function executeSend() {
        if (!window.emailjs) {
          submitBtn.disabled = false;
          setStatus('error', 'Could not load EmailJS. Please check your internet connection.');
          return;
        }
        // 4-arg API: send(serviceId, templateId, params, publicKey)
        window.emailjs.send(svc, tpl, data, pub)
          .then(function () {
            setStatus('success', '🎉 Thanks, ' + data.from_name + '! Your message was sent. I\'ll get back to you shortly.');
            form.reset();
          })
          .catch(function (err) {
            console.error('EmailJS error:', err);
            var msg = (err && (err.text || err.message)) ? ' (' + (err.text || err.message) + ')' : '';
            setStatus('error', 'Failed to send' + msg + '. Please verify your EmailJS credentials in the Advanced tab.');
          })
          .finally(function () { submitBtn.disabled = false; });
      }

      if (!window.emailjs) {
        loadEmailJs(executeSend);
      } else {
        executeSend();
      }
    });
  }

  // ── Contact card ────────────────────────────────────────────────────────────
  var contactMount = $('[data-ch-mount="contact"]');
  if (contactMount) {
    var title = props.contactCardTitle || 'Other Ways to Reach Me';
    var sub = props.contactCardSubtitle || '';
    var showPhone    = props.showPhone    !== false && props.showPhone    !== 'false';
    var showViber    = props.showViber    !== false && props.showViber    !== 'false';
    var showWhatsapp = props.showWhatsapp !== false && props.showWhatsapp !== 'false';

    var phone    = (props.phoneNumber    || '').trim();
    var viber    = (props.viberNumber    || '').replace(/[^0-9]/g, '');
    var whatsapp = (props.whatsappNumber || '').replace(/[^0-9]/g, '');

    var links = [];

    if (showPhone && phone) {
      links.push(
        '<a class="wb-ch-contact-link" href="tel:' + esc(phone) + '">' +
          '<span class="wb-ch-contact-icon wb-ch-icon-phone" aria-hidden="true">📞</span>' +
          '<span class="wb-ch-contact-text">' +
            '<span class="wb-ch-contact-name">Call Me</span>' +
            '<span class="wb-ch-contact-value">' + esc(phone) + '</span>' +
          '</span>' +
          '<span class="wb-ch-contact-arrow" aria-hidden="true">›</span>' +
        '</a>'
      );
    }
    if (showViber && viber) {
      // viber://chat?number=DIGITS — correct mobile deep link
      links.push(
        '<a class="wb-ch-contact-link" href="viber://chat?number=' + esc(viber) + '" target="_blank" rel="noopener noreferrer">' +
          '<span class="wb-ch-contact-icon wb-ch-icon-viber" aria-hidden="true">💜</span>' +
          '<span class="wb-ch-contact-text">' +
            '<span class="wb-ch-contact-name">Viber</span>' +
            '<span class="wb-ch-contact-value">Chat on Viber</span>' +
          '</span>' +
          '<span class="wb-ch-contact-arrow" aria-hidden="true">›</span>' +
        '</a>'
      );
    }
    if (showWhatsapp && whatsapp) {
      links.push(
        '<a class="wb-ch-contact-link" href="https://wa.me/' + esc(whatsapp) + '" target="_blank" rel="noopener noreferrer">' +
          '<span class="wb-ch-contact-icon wb-ch-icon-whatsapp" aria-hidden="true">💚</span>' +
          '<span class="wb-ch-contact-text">' +
            '<span class="wb-ch-contact-name">WhatsApp</span>' +
            '<span class="wb-ch-contact-value">Message on WhatsApp</span>' +
          '</span>' +
          '<span class="wb-ch-contact-arrow" aria-hidden="true">›</span>' +
        '</a>'
      );
    }

    contactMount.innerHTML =
      '<h3 class="wb-ch-contact-title">' + esc(title) + '</h3>' +
      (sub ? '<p class="wb-ch-contact-sub">' + esc(sub) + '</p>' : '') +
      (links.length
        ? '<div class="wb-ch-contact-links">' + links.join('') + '</div>'
        : '<div class="wb-ch-empty">Add your phone, Viber, or WhatsApp number in the Inspector to show contact options.</div>');
  }

  el.__wbDestroy = function () {};
}

