customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-livechat-anchor') || el;
  if (!root) return;

  var provider = props.provider || 'whatsapp';
  var pos = props.position || 'bottom-right';
  var label = props.buttonLabel || 'Chat with us';
  var accent = props.accentColor || '#25d366';
  var esc = function(s) { return String(s || '').replace(/[&<>"']/g, function(c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };

  // 1. WhatsApp Floating Button
  if (provider === 'whatsapp') {
    var rawPhone = (props.whatsappNumber || '').replace(/[^0-9]/g, '');
    var msg = encodeURIComponent(props.whatsappMessage || 'Hello!');
    var href = rawPhone ? ('https://wa.me/' + rawPhone + '?text=' + msg) : '#';

    var btn = document.createElement('a');
    btn.className = 'wb-livechat-fab wb-livechat-fab--' + pos;
    btn.href = href;
    btn.target = '_blank';
    btn.rel = 'noopener noreferrer';
    btn.style.setProperty('--lc-accent', accent);
    btn.innerHTML = '<span class="wb-livechat-icon" aria-hidden="true">💚</span><span class="wb-livechat-label">' + esc(label) + '</span><span class="wb-livechat-pulse"></span>';

    // Remove any previous widget
    var prev = document.querySelector('.wb-livechat-fab');
    if (prev) prev.remove();

    document.body.appendChild(btn);

    el.__wbDestroy = function() {
      if (btn && btn.parentNode) btn.parentNode.removeChild(btn);
    };
    return;
  }

  // 2. Tawk.to Free Live Chat
  if (provider === 'tawk') {
    var propId = (props.propertyId || '').trim();
    if (!propId) return;
    if (document.querySelector('script[src*="tawk.to"]')) return;

    window.Tawk_API = window.Tawk_API || {};
    window.Tawk_LoadStart = new Date();
    var s = document.createElement('script');
    s.async = true;
    s.src = 'https://embed.tawk.to/' + propId + '/default';
    s.charset = 'UTF-8';
    s.setAttribute('crossorigin', '*');
    document.head.appendChild(s);
    return;
  }

  // 3. Crisp Customer Messaging
  if (provider === 'crisp') {
    var crispId = (props.propertyId || '').trim();
    if (!crispId) return;
    if (document.querySelector('script[src*="client.crisp.chat"]')) return;

    window.$crisp = [];
    window.CRISP_WEBSITE_ID = crispId;
    var s2 = document.createElement('script');
    s2.src = 'https://client.crisp.chat/l.js';
    s2.async = true;
    document.head.appendChild(s2);
    return;
  }

  // 4. Custom Script Embed
  if (provider === 'custom') {
    var scriptUrl = (props.embedScriptUrl || '').trim();
    if (!scriptUrl) return;
    if (document.querySelector('script[src="' + scriptUrl + '"]')) return;

    var s3 = document.createElement('script');
    s3.src = scriptUrl;
    s3.async = true;
    document.head.appendChild(s3);
  }

  el.__wbDestroy = function() {};
}

