.cg-checkout-btn {
  width: 100%;
  padding: 14px;
  border-radius: 12px;
  background: var(--grid-accent, #e11d48);
  color: #fff;
  border: none;
  font-weight: 800;
  font-size: 1rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: opacity 0.2s;
}
.cg-checkout-btn:hover {
  opacity: 0.93;
}
/* Booking & Checkout Modal */
.cg-modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(6px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}
.cg-modal-backdrop.open {
  opacity: 1;
  pointer-events: auto;
}
.cg-modal-card {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  max-width: 540px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  padding: 28px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
  color: #fff;
  position: relative;
}
.cg-modal-close {
  position: absolute;
  top: 18px;
  right: 20px;
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 1.6rem;
  cursor: pointer;
}
.cg-modal-close:hover {
  color: #fff;
}
.cg-form-group {
  margin-bottom: 16px;
}
.cg-form-label {
  display: block;
  font-size: 0.82rem;
  font-weight: 700;
  color: #cbd5e1;
  margin-bottom: 6px;
}
.cg-input, .cg-textarea, .cg-select {
  width: 100%;
  padding: 11px 14px;
  border-radius: 10px;
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: 0.92rem;
  font-family: inherit;
  outline: none;
  box-sizing: border-box;
}
.cg-input:focus, .cg-textarea:focus, .cg-select:focus {
  border-color: var(--grid-accent, #e11d48);
}
.cg-order-summary-box {
  background: #0f172a;
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.cg-success-box {
  text-align: center;
  padding: 20px 10px;
}
.cg-success-icon {
  font-size: 3.5rem;
  margin-bottom: 10px;
}
.cg-channel-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 18px;
  border-radius: 12px;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  color: #fff;
  margin-top: 10px;
  transition: opacity 0.2s;
}
.cg-channel-btn:hover {
  opacity: 0.9;
}
.cg-channel-whatsapp {
  background: #25d366;
  color: #0b2e13;
}
.cg-channel-messenger {
  background: #0084ff;
  color: #fff;
}
.cg-sync-badge {
  display: inline-block;
  margin-top: 14px;
  font-size: 0.75rem;
  color: #94a3b8;
  text-align: center;
  width: 100%;
}
@media (max-width: 600px) {
  .cg-title { font-size: 1.8rem; }
  .cg-floating-cart { bottom: 18px; right: 18px; padding: 11px 18px; }
}

customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-culinary-grid');
  var mount = el.querySelector('[data-cg-mount]');
  var tabsContainer = el.querySelector('[data-cg-tabs]');
  var cartMount = el.querySelector('[data-cg-cart]');
  if (!root || !mount) return;

  var esc = function(s) {
    return String(s || '').replace(/[&<>"']/g, function(c) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  };

  var currencySym = '₱';
  var allProducts = [];
  var currentCategory = props.filterCategory && props.filterCategory !== 'All' ? props.filterCategory : 'All';
  var selectedProductState = {}; // { [prodId]: { varIdx: 0, qty: 1 } }
  var cart = [];

  // Determine API base dynamically (supports custom external domain / multi-client bot URL)
  var apiBase = (function() {
    if (props.externalCatalogUrl && props.externalCatalogUrl.trim()) {
      var ext = props.externalCatalogUrl.trim();
      if (!ext.endsWith('api.php') && !ext.endsWith('.php')) {
        ext = ext.replace(/\/?$/, '/api.php');
      }
      return ext;
    }
    var s = window.location.pathname.replace(/\/[^\/]*$/, '/');
    return window.location.origin + s + 'api.php';
  })();

  // Render Tabs
  function renderTabs() {
    if (!tabsContainer || props.showCategoryTabs === false) {
      if (tabsContainer) tabsContainer.style.display = 'none';
      return;
    }
    tabsContainer.style.display = 'flex';
    var catSet = {};
    allProducts.forEach(function(p) {
      var c = (p.category || p.tag || '').trim();
      if (c) catSet[c] = true;
    });
    var cats = ['All'].concat(Object.keys(catSet));
    tabsContainer.innerHTML = cats.map(function(c) {
      var activeCls = (c === currentCategory) ? ' active' : '';
      return '<button type="button" class="cg-tab-btn' + activeCls + '" data-cg-cat="' + esc(c) + '">' + esc(c) + '</button>';
    }).join('');

    var tabBtns = tabsContainer.querySelectorAll('.cg-tab-btn');
    tabBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        tabBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        currentCategory = btn.getAttribute('data-cg-cat');
        renderGrid();
      });
    });
  }

  // Render Product Grid
  function renderGrid() {
    var filtered = allProducts.filter(function(p) {
      if (currentCategory === 'All') return true;
      var c = (p.category || p.tag || '').trim();
      return c.toLowerCase() === currentCategory.toLowerCase();
    });

    if (filtered.length === 0) {
      mount.innerHTML = '<div style="grid-column: 1/-1; text-align: center; color: #94a3b8; padding: 40px;">No items found in category <strong>' + esc(currentCategory) + '</strong>.</div>';
      return;
    }

    mount.innerHTML = filtered.map(function(item, idx) {
      var id = item.id != null ? String(item.id) : ('item_' + idx);
      if (!selectedProductState[id]) {
        selectedProductState[id] = { varIdx: 0, qty: 1 };
      }
      var state = selectedProductState[id];

      var imgHtml = item.imageUrl
        ? '<img class="cg-img" src="' + esc(item.imageUrl) + '" alt="' + esc(item.name) + '" loading="lazy">'
        : '<div class="cg-img" style="display:flex;align-items:center;justify-content:center;color:#64748b;font-size:2.8rem;">🎂</div>';

      var tagHtml = item.tag ? '<div class="cg-tag">' + esc(item.tag) + '</div>' : '';

      var isBooking = (item.fulfillment_mode === 'booking');
      var isPhysical = (item.fulfillment_mode === 'physical');
      var stock = (item.stock_quantity != null) ? parseInt(item.stock_quantity) : null;

      var fulfillTag = '';
      if (isBooking) {
        fulfillTag = '<div class="cg-fulfillment-tag cg-tag-booking">📅 Booking / Pre-order</div>';
      } else if (isPhysical && stock !== null) {
        if (stock <= 0) {
          fulfillTag = '<div class="cg-fulfillment-tag cg-tag-out">⚠️ Out of Stock</div>';
        } else {
          fulfillTag = '<div class="cg-fulfillment-tag cg-tag-stock">📦 ' + stock + ' in stock</div>';
        }
      }

      // Variations pills
      var vars = Array.isArray(item.variations) ? item.variations : [];
      var activeVar = vars[state.varIdx] || null;
      var activePrice = activeVar && activeVar.price != null
        ? (currencySym + parseFloat(activeVar.price).toFixed(2))
        : (item.priceFormatted || item.price || '₱0.00');

      var activeDesc = (activeVar && activeVar.description) ? activeVar.description : (item.description || '');

      var varsHtml = '';
      if (vars.length > 0) {
        var pills = vars.map(function(v, vi) {
          var act = (vi === state.varIdx) ? ' active' : '';
          var vPrice = v.price != null ? (currencySym + parseFloat(v.price).toFixed(0)) : '';
          return '<button type="button" class="cg-var-pill' + act + '" data-prod-id="' + esc(id) + '" data-var-idx="' + vi + '">' + esc(v.name) + ' (' + vPrice + ')</button>';
        }).join('');
        varsHtml = '<div class="cg-variations-section"><span class="cg-var-label">Available Layers / Sizes:</span><div class="cg-var-pills">' + pills + '</div></div>';
      }

      var isOut = isPhysical && (stock !== null && stock <= 0);
      var btnText = isOut ? 'Sold Out' : (props.btnText || 'Add to Cart');

      return '<div class="cg-card" data-card-id="' + esc(id) + '">'
        + '<div class="cg-img-wrap">' + imgHtml + tagHtml + fulfillTag + '</div>'
        + '<div class="cg-info">'
        + '<h3 class="cg-name">' + esc(item.name) + '</h3>'
        + '<p class="cg-desc" data-cg-desc>' + esc(activeDesc) + '</p>'
        + varsHtml
        + '<div class="cg-price-row">'
        + '<div class="cg-price" data-cg-price>' + esc(activePrice) + '</div>'
        + '</div>'
        + '<div class="cg-card-actions">'
        + '<button type="button" class="cg-qty-btn" data-cg-dec="' + esc(id) + '">−</button>'
        + '<span class="cg-qty-display" data-cg-qty="' + esc(id) + '">' + state.qty + '</span>'
        + '<button type="button" class="cg-qty-btn" data-cg-inc="' + esc(id) + '">+</button>'
        + '<button type="button" class="cg-add-btn" data-cg-add="' + esc(id) + '"' + (isOut ? ' disabled' : '') + '>'
        + (isBooking ? '📅 ' : '🛒 ') + esc(btnText)
        + '</button>'
        + '</div>'
        + '</div>'
        + '</div>';
    }).join('');

    bindGridEvents();
  }

  function bindGridEvents() {
    // Variation selection
    mount.querySelectorAll('.cg-var-pill').forEach(function(pill) {
      pill.addEventListener('click', function(e) {
        e.stopPropagation();
        var prodId = pill.getAttribute('data-prod-id');
        var varIdx = parseInt(pill.getAttribute('data-var-idx'));
        if (!selectedProductState[prodId]) selectedProductState[prodId] = { varIdx: 0, qty: 1 };
        selectedProductState[prodId].varIdx = varIdx;

        var card = mount.querySelector('.cg-card[data-card-id="' + prodId + '"]');
        if (card) {
          card.querySelectorAll('.cg-var-pill').forEach(function(p) { p.classList.remove('active'); });
          pill.classList.add('active');

          var prod = allProducts.find(function(p, i) { return (p.id != null ? String(p.id) : ('item_' + i)) === prodId; });
          if (prod && Array.isArray(prod.variations) && prod.variations[varIdx]) {
            var vObj = prod.variations[varIdx];
            var priceEl = card.querySelector('[data-cg-price]');
            if (priceEl && vObj.price != null) {
              priceEl.textContent = currencySym + parseFloat(vObj.price).toFixed(2);
            }
            var descEl = card.querySelector('[data-cg-desc]');
            if (descEl) {
              descEl.textContent = vObj.description || prod.description || '';
            }
          }
        }
      });
    });

    // Quantity buttons
    mount.querySelectorAll('[data-cg-inc]').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var id = btn.getAttribute('data-cg-inc');
        if (!selectedProductState[id]) selectedProductState[id] = { varIdx: 0, qty: 1 };
        selectedProductState[id].qty++;
        var disp = mount.querySelector('[data-cg-qty="' + id + '"]');
        if (disp) disp.textContent = selectedProductState[id].qty;
      });
    });

    mount.querySelectorAll('[data-cg-dec]').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var id = btn.getAttribute('data-cg-dec');
        if (!selectedProductState[id]) selectedProductState[id] = { varIdx: 0, qty: 1 };
        if (selectedProductState[id].qty > 1) {
          selectedProductState[id].qty--;
          var disp = mount.querySelector('[data-cg-qty="' + id + '"]');
          if (disp) disp.textContent = selectedProductState[id].qty;
        }
      });
    });

    // Add to cart
    mount.querySelectorAll('[data-cg-add]').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var id = btn.getAttribute('data-cg-add');
        var prod = allProducts.find(function(p, i) { return (p.id != null ? String(p.id) : ('item_' + i)) === id; });
        if (!prod) return;

        var st = selectedProductState[id] || { varIdx: 0, qty: 1 };
        var vars = Array.isArray(prod.variations) ? prod.variations : [];
        var vObj = vars[st.varIdx] || null;

        var priceVal = vObj && vObj.price != null ? parseFloat(vObj.price) : (parseFloat(prod.price) || 0);
        var varName = vObj ? vObj.name : '';
        var cartKey = id + '_' + st.varIdx;

        var existing = cart.find(function(c) { return c.key === cartKey; });
        if (existing) {
          existing.qty += st.qty;
        } else {
          cart.push({
            key: cartKey,
            productId: prod.id || null,
            name: prod.name,
            variation: varName,
            price: priceVal,
            qty: st.qty,
            imageUrl: prod.imageUrl || '',
            fulfillment_mode: prod.fulfillment_mode || 'physical'
          });
        }

        // Reset card quantity counter
        st.qty = 1;
        var disp = mount.querySelector('[data-cg-qty="' + id + '"]');
        if (disp) disp.textContent = '1';

        updateCartUI();
        openDrawer();
      });
    });
  }

  // Mount Shopping Cart & Drawer UI
  function initCartUI() {
    if (props.enableCart === false) return;

    var container = document.createElement('div');
    container.innerHTML = ''
      + '<div class="cg-floating-cart" data-open-cart>'
      + '<span>🛒 View Cart</span>'
      + '<span class="cg-cart-count-badge" data-cg-badge>0</span>'
      + '</div>'
      + '<div class="cg-drawer-backdrop" data-drawer-backdrop></div>'
      + '<div class="cg-drawer" data-drawer>'
      + '<div class="cg-drawer-header">'
      + '<h3 class="cg-drawer-title">Your Order Cart</h3>'
      + '<button type="button" class="cg-drawer-close" data-close-drawer>&times;</button>'
      + '</div>'
      + '<div class="cg-drawer-body" data-drawer-body></div>'
      + '<div class="cg-drawer-footer">'
      + '<div class="cg-subtotal-row">'
      + '<span class="cg-subtotal-label">Estimated Total:</span>'
      + '<span class="cg-subtotal-val" data-cart-total>₱0.00</span>'
      + '</div>'
      + '<button type="button" class="cg-checkout-btn" data-start-checkout>'
      + 'Proceed to Book / Order &rarr;'
      + '</button>'
      + '</div>'
      + '</div>'
      + '<div class="cg-modal-backdrop" data-checkout-modal>'
      + '<div class="cg-modal-card" data-modal-card></div>'
      + '</div>';

    root.appendChild(container);

    root.querySelector('[data-open-cart]').addEventListener('click', openDrawer);
    root.querySelector('[data-close-drawer]').addEventListener('click', closeDrawer);
    root.querySelector('[data-drawer-backdrop]').addEventListener('click', closeDrawer);
    root.querySelector('[data-start-checkout]').addEventListener('click', openCheckoutModal);
  }

  function openDrawer() {
    var d = root.querySelector('[data-drawer]');
    var b = root.querySelector('[data-drawer-backdrop]');
    if (d) d.classList.add('open');
    if (b) b.classList.add('open');
  }

  function closeDrawer() {
    var d = root.querySelector('[data-drawer]');
    var b = root.querySelector('[data-drawer-backdrop]');
    if (d) d.classList.remove('open');
    if (b) b.classList.remove('open');
  }

  function updateCartUI() {
    var badge = root.querySelector('[data-cg-badge]');
    var totalCount = cart.reduce(function(sum, item) { return sum + item.qty; }, 0);
    if (badge) badge.textContent = totalCount;

    var totalSum = cart.reduce(function(sum, item) { return sum + (item.price * item.qty); }, 0);
    var totalEl = root.querySelector('[data-cart-total]');
    if (totalEl) totalEl.textContent = currencySym + totalSum.toFixed(2);

    var body = root.querySelector('[data-drawer-body]');
    if (!body) return;

    if (cart.length === 0) {
      body.innerHTML = '<div style="text-align: center; color: #94a3b8; padding: 60px 20px;">'
        + '<div style="font-size: 3rem; margin-bottom: 12px;">🛒</div>'
        + '<p style="font-size: 1.05rem; font-weight: 600; color: #fff;">Your cart is empty</p>'
        + '<p style="font-size: 0.85rem;">Select items from the menu to build your event order or booking.</p>'
        + '</div>';
      var chkBtn = root.querySelector('[data-start-checkout]');
      if (chkBtn) chkBtn.style.opacity = '0.5';
      return;
    }

    var chkBtn2 = root.querySelector('[data-start-checkout]');
    if (chkBtn2) chkBtn2.style.opacity = '1';

    body.innerHTML = cart.map(function(item, idx) {
      var img = item.imageUrl
        ? '<img class="cg-cart-item-img" src="' + esc(item.imageUrl) + '" alt="' + esc(item.name) + '">'
        : '<div class="cg-cart-item-img" style="display:flex;align-items:center;justify-content:center;color:#64748b;font-size:1.5rem;">🎂</div>';

      var sub = item.variation ? ('Layer / Size: ' + esc(item.variation)) : (item.fulfillment_mode === 'booking' ? 'Custom Booking Style' : 'Direct Order');

      return '<div class="cg-cart-item">'
        + img
        + '<div class="cg-cart-item-info">'
        + '<div class="cg-cart-item-title">' + esc(item.name) + '</div>'
        + '<div class="cg-cart-item-sub">' + sub + '</div>'
        + '<div class="cg-cart-item-price">' + currencySym + (item.price * item.qty).toFixed(2) + ' <span style="font-weight:400;color:#94a3b8;font-size:0.75rem;">(' + item.qty + ' &times; ' + currencySym + item.price.toFixed(2) + ')</span></div>'
        + '</div>'
        + '<button type="button" class="cg-cart-item-remove" data-cart-remove="' + idx + '" title="Remove item">&times;</button>'
        + '</div>';
    }).join('');

    body.querySelectorAll('[data-cart-remove]').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var i = parseInt(btn.getAttribute('data-cart-remove'));
        cart.splice(i, 1);
        updateCartUI();
      });
    });
  }

  // Booking & Checkout Modal
  function openCheckoutModal() {
    if (cart.length === 0) return;
    closeDrawer();

    var modal = root.querySelector('[data-checkout-modal]');
    var card = root.querySelector('[data-modal-card]');
    if (!modal || !card) return;

    var hasBookingItem = cart.some(function(c) { return c.fulfillment_mode === 'booking'; });
    var totalSum = cart.reduce(function(sum, item) { return sum + (item.price * item.qty); }, 0);

    var itemsSummaryHtml = cart.map(function(c) {
      return '<div style="display:flex; justify-content:space-between; font-size:0.85rem; margin-bottom:4px;">'
        + '<span>' + c.qty + '&times; ' + esc(c.name) + (c.variation ? ' (' + esc(c.variation) + ')' : '') + '</span>'
        + '<strong>' + currencySym + (c.price * c.qty).toFixed(2) + '</strong>'
        + '</div>';
    }).join('');

    card.innerHTML = ''
      + '<button type="button" class="cg-modal-close" data-close-modal>&times;</button>'
      + '<h2 style="font-size: 1.4rem; font-weight: 800; margin: 0 0 4px;">Confirm Your Booking & Order</h2>'
      + '<p style="color: #94a3b8; font-size: 0.85rem; margin: 0 0 18px;">Please provide your event and contact information below:</p>'
      + '<div class="cg-order-summary-box">'
      + '<div style="font-size:0.75rem; text-transform:uppercase; color:#94a3b8; font-weight:700; margin-bottom:8px;">Order Items:</div>'
      + itemsSummaryHtml
      + '<div style="border-top:1px solid rgba(255,255,255,0.1); margin-top:8px; padding-top:8px; display:flex; justify-content:space-between; font-weight:800; font-size:1rem;">'
      + '<span>Total:</span><span style="color:var(--grid-accent, #e11d48);">' + currencySym + totalSum.toFixed(2) + '</span>'
      + '</div>'
      + '</div>'
      + '<form data-booking-form>'
      + '<div class="cg-form-group">'
      + '<label class="cg-form-label">Full Name *</label>'
      + '<input type="text" name="customer_name" class="cg-input" required placeholder="e.g. Maria Santos">'
      + '</div>'
      + '<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">'
      + '<div class="cg-form-group">'
      + '<label class="cg-form-label">Phone / WhatsApp *</label>'
      + '<input type="tel" name="phone" class="cg-input" required placeholder="0917xxxxxxx">'
      + '</div>'
      + '<div class="cg-form-group">'
      + '<label class="cg-form-label">Email Address</label>'
      + '<input type="email" name="email" class="cg-input" placeholder="name@email.com">'
      + '</div>'
      + '</div>'
      + (hasBookingItem ? (
        '<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">'
        + '<div class="cg-form-group">'
        + '<label class="cg-form-label">Event / Pickup Date *</label>'
        + '<input type="date" name="event_date" class="cg-input" required>'
        + '</div>'
        + '<div class="cg-form-group">'
        + '<label class="cg-form-label">Preferred Time</label>'
        + '<input type="time" name="event_time" class="cg-input">'
        + '</div>'
        + '</div>'
        + '<div class="cg-form-group">'
        + '<label class="cg-form-label">🎂 Dedication Text on Cake</label>'
        + '<textarea name="cake_dedication" class="cg-textarea" rows="2" placeholder="e.g. Happy 18th Birthday Chloe! Love, Mom & Dad"></textarea>'
        + '</div>'
      ) : '')
      + '<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">'
      + '<div class="cg-form-group">'
      + '<label class="cg-form-label">Fulfillment</label>'
      + '<select name="delivery_type" class="cg-select">'
      + '<option value="pickup">Store Pickup</option>'
      + '<option value="delivery">Delivery</option>'
      + '</select>'
      + '</div>'
      + '<div class="cg-form-group">'
      + '<label class="cg-form-label">Delivery Address / Notes</label>'
      + '<input type="text" name="delivery_address" class="cg-input" placeholder="Barangay, City or Pickup time">'
      + '</div>'
      + '</div>'
      + '<button type="submit" class="cg-checkout-btn" style="margin-top:10px;" data-submit-btn>'
      + 'Submit Booking & Order'
      + '</button>'
      + '</form>';

    modal.classList.add('open');

    card.querySelector('[data-close-modal]').addEventListener('click', function() {
      modal.classList.remove('open');
    });

    // Form submit
    var form = card.querySelector('[data-booking-form]');
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      var submitBtn = card.querySelector('[data-submit-btn]');
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Submitting your booking...';
      }

      var fd = new FormData(form);
      var bookingPayload = {
        customer_name: fd.get('customer_name') || '',
        phone: fd.get('phone') || '',
        email: fd.get('email') || '',
        event_date: fd.get('event_date') || '',
        event_time: fd.get('event_time') || '',
        cake_dedication: fd.get('cake_dedication') || '',
        delivery_type: fd.get('delivery_type') || 'pickup',
        delivery_address: fd.get('delivery_address') || '',
        items: cart,
        total_amount: totalSum
      };

      // 1. Post to elementor-builder api.php?action=create_booking
      fetch(apiBase + '?action=create_booking', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bookingPayload)
      })
      .then(function(res) { return res.json(); })
      .catch(function() { return { success: true, booking_ref: 'BK-' + Math.floor(100000 + Math.random() * 900000) }; })
      .then(function(resp) {
        var ref = (resp && resp.booking_ref) ? resp.booking_ref : ('BK-' + Math.floor(100000 + Math.random() * 900000));

        // 2. Optional: Send to Google Apps Script Web App
        var googleUrl = (props.googleWebAppUrl || '').trim();
        if (googleUrl && googleUrl.indexOf('http') === 0) {
          try {
            fetch(googleUrl, {
              method: 'POST',
              mode: 'no-cors',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(Object.assign({}, bookingPayload, { booking_ref: ref }))
            }).catch(function() {});
          } catch(err) {}
        }

        // Render success state with 1-click notification links
        var ownerPhone = (props.ownerPhone || '').replace(/[^0-9]/g, '');
        var ownerMessenger = (props.ownerMessenger || '').trim();

        var summaryLines = [
          'Hello! I placed a new booking/order on your website:',
          'Ref: #' + ref,
          'Name: ' + bookingPayload.customer_name,
          'Phone: ' + bookingPayload.phone,
          bookingPayload.event_date ? ('Event Date: ' + bookingPayload.event_date + (bookingPayload.event_time ? (' ' + bookingPayload.event_time) : '')) : '',
          bookingPayload.cake_dedication ? ('Dedication: "' + bookingPayload.cake_dedication + '"') : '',
          'Items: ' + cart.map(function(c) { return c.qty + 'x ' + c.name + (c.variation ? ' [' + c.variation + ']' : ''); }).join(', '),
          'Total: ' + currencySym + totalSum.toFixed(2),
          'Fulfillment: ' + bookingPayload.delivery_type + (bookingPayload.delivery_address ? (' (' + bookingPayload.delivery_address + ')') : '')
        ].filter(Boolean).join('\n');

        var waUrl = ownerPhone ? ('https://wa.me/' + ownerPhone + '?text=' + encodeURIComponent(summaryLines)) : '';
        var fbUrl = ownerMessenger ? ('https://m.me/' + ownerMessenger) : '';

        card.innerHTML = ''
          + '<button type="button" class="cg-modal-close" data-close-modal>&times;</button>'
          + '<div class="cg-success-box">'
          + '<div class="cg-success-icon">🎉</div>'
          + '<h2 style="font-size:1.5rem; font-weight:800; margin:0 0 6px;">Booking Placed Successfully!</h2>'
          + '<p style="color:#94a3b8; font-size:0.9rem; margin:0 0 16px;">Booking Reference: <strong style="color:var(--grid-accent, #e11d48);">#' + esc(ref) + '</strong></p>'
          + '<p style="font-size:0.88rem; color:#cbd5e1; line-height:1.5; margin-bottom:20px;">'
          + 'Thank you, <strong>' + esc(bookingPayload.customer_name) + '</strong>! Your order has been submitted to the dashboard.'
          + '</p>'
          + (waUrl ? (
            '<a href="' + esc(waUrl) + '" target="_blank" rel="noopener" class="cg-channel-btn cg-channel-whatsapp">'
            + '<span>💬 Send Order Summary to Owner via WhatsApp</span>'
            + '</a>'
          ) : '')
          + (fbUrl ? (
            '<a href="' + esc(fbUrl) + '" target="_blank" rel="noopener" class="cg-channel-btn cg-channel-messenger">'
            + '<span>⚡ Message Us on Facebook Messenger</span>'
            + '</a>'
          ) : '')
          + '<button type="button" class="cg-checkout-btn" style="margin-top:20px; background:rgba(255,255,255,0.08);" data-finish-btn>'
          + 'Close & Continue Browsing'
          + '</button>'
          + '</div>';

        // Clear cart
        cart = [];
        updateCartUI();

        card.querySelectorAll('[data-close-modal], [data-finish-btn]').forEach(function(b) {
          b.addEventListener('click', function() {
            modal.classList.remove('open');
          });
        });
      });
    });
  }

  // Initial Load: map static items
  var staticItems = (props.items || []).map(function(item) {
    return {
      name: item.name || '',
      price: item.price || '₱0.00',
      priceFormatted: item.price || '₱0.00',
      imageUrl: item.imageUrl || '',
      tag: item.tag || item.category || '',
      category: item.category || item.tag || 'Cakes',
      description: item.description || '',
      fulfillment_mode: item.fulfillment_mode || (item.category === 'Utensils' ? 'physical' : 'booking'),
      stock_quantity: item.stock_quantity != null ? item.stock_quantity : (item.category === 'Utensils' ? 20 : null),
      variations: Array.isArray(item.variations) ? item.variations : []
    };
  });

  allProducts = staticItems;
  renderTabs();
  renderGrid();
  initCartUI();

  // Live Auto-Sync from Bot Catalog
  if (props.syncLiveCatalog !== false) {
    fetch(apiBase + '?action=get_catalog_products', { cache: 'no-store' })
      .then(function(r) { return r.ok ? r.json() : null; })
      .then(function(data) {
        if (!data || !data.success || !Array.isArray(data.products) || data.products.length === 0) return;

        var mapped = data.products.map(function(p) {
          var curr = p.currency === 'PHP' ? '₱' : (p.currency === 'USD' ? '$' : (p.currency ? p.currency + ' ' : '₱'));
          currencySym = curr;

          var parsedVars = [];
          if (p.variations) {
            try {
              parsedVars = typeof p.variations === 'string' ? JSON.parse(p.variations) : p.variations;
            } catch(e) {}
          }

          return {
            id: p.id,
            name: p.name || '',
            price: parseFloat(p.price || 0),
            priceFormatted: curr + parseFloat(p.price || 0).toFixed(2),
            imageUrl: p.image_url || '',
            tag: p.category || '',
            category: p.category || '',
            description: p.description || '',
            fulfillment_mode: p.fulfillment_mode || 'booking',
            stock_quantity: p.stock_quantity != null ? parseInt(p.stock_quantity) : null,
            variations: parsedVars
          };
        });

        allProducts = mapped;
        renderTabs();
        renderGrid();

        // Live badge
        var badge = root.querySelector('.cg-sync-badge');
        if (!badge) {
          badge = document.createElement('div');
          badge.className = 'cg-sync-badge';
          root.appendChild(badge);
        }
        badge.innerHTML = '🟢 <strong>Live Sync Active</strong> &mdash; ' + mapped.length + ' products loaded from catalog';
      })
      .catch(function() { /* Keep static fallback items cleanly */ });
  }

  el.__wbDestroy = function() {
    var floatCart = root.querySelector('.cg-floating-cart');
    if (floatCart) floatCart.remove();
    var backdrop = root.querySelector('.cg-drawer-backdrop');
    if (backdrop) backdrop.remove();
    var drawer = root.querySelector('.cg-drawer');
    if (drawer) drawer.remove();
    var modal = root.querySelector('[data-checkout-modal]');
    if (modal) modal.remove();
  };
}

customCss:
.wb-faq-addon-wrapper {
  padding: 40px 20px;
  max-width: 900px;
  margin: 0 auto;
}
.wb-faq-header {
  text-align: center;
  margin-bottom: 30px;
}
.wb-faq-title {
  font-size: 2rem;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 8px 0;
}
.wb-faq-sub {
  font-size: 0.95rem;
  color: #94a3b8;
  margin: 0 0 20px 0;
}
.wb-faq-search-box {
  max-width: 460px;
  margin: 0 auto;
  position: relative;
  display: flex;
  align-items: center;
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  padding: 0 14px;
}
.wb-faq-search-input {
  width: 100%;
  padding: 10px 10px 10px 8px;
  background: transparent;
  border: none;
  color: #ffffff;
  font-size: 0.9rem;
  outline: none;
}
.wb-faq-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.wb-faq-item {
  background: rgba(19, 27, 46, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  overflow: hidden;
  transition: all 0.25s ease;
}
.wb-faq-item[open] {
  border-color: var(--faq-accent, #38bdf8);
  box-shadow: 0 10px 25px -10px rgba(56, 189, 248, 0.25);
}
.wb-faq-question {
  padding: 18px 22px;
  font-size: 1rem;
  font-weight: 700;
  color: #ffffff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  list-style: none;
  user-select: none;
}
.wb-faq-question::-webkit-details-marker {
  display: none;
}
.wb-faq-toggle-icon {
  font-size: 1.4rem;
  color: var(--faq-accent, #38bdf8);
  transition: transform 0.25s ease;
}
.wb-faq-item[open] .wb-faq-toggle-icon {
  transform: rotate(45deg);
}
.wb-faq-answer {
  padding: 0 22px 18px 22px;
  font-size: 0.9rem;
  line-height: 1.6;
  color: #cbd5e1;
}
